;---------------------------------------------------------------------------------------------------
; AdaptiveMemory_DetermineWhichCellApplies_MM  ($4D8B)
;
; Selects the adaptive memory cell for the current operating point. [reviewed]
;
; - Closed throttle and RPM below target idle + IDLOFS (+ HYTRPM hysteresis when already in an
;   idle cell): idle cell 12, or cell 13 when BitFlags_AIS bit 3 is set (a second idle load
;   state).
; - Otherwise: six MAP bands separated by MP1..MP5 (hysteresis DLTMAP) times two RPM bands
;   separated by R1 (hysteresis DLTRPM) give cells 0-11. When the cell changes, BitFlags37 bit 7
;   is set so the controller restarts its averaging.
;
; Called from: MainSubLoop
;---------------------------------------------------------------------------------------------------
AdaptiveMemory_DetermineWhichCellApplies_MM:
        clra
        staa    <Temp0
        ldx     #MP1_AutoCalMapCellBoundary1         ; MP1: AutoCalMapCellBoundary1
        ldab    <PointerIntoAdaptiveMemory
        brset   <BitFlags65,#$80,ONTHROTTLE_OR_RPMTOOHIGHFORIDLE ; throttle open (off idle)
        ldaa    <TargetIdleSpeedHB
        adda    >IDLOFS_DeltaForIdleRPMForClosedThrottleCell ; IDLOFS: RPM Delta for Idle RPM For Closed Throttle Cell
        cmpb    #$0C
        bcs     L4DA3
        adda    >HYTRPM_HysteresisFor_IDLOFS         ; HYTRPM: Hysteresis for IDLOFS
L4DA3:
        cmpa    <EngineRpm_HB
        bcs     ONTHROTTLE_OR_RPMTOOHIGHFORIDLE
        ldab    #$0C
        brset   <BitFlags_AIS,#$08,L4DDA
        incb
        bra     L4DDA

L4DB0:
        ldaa    $00,x
        cmpb    <Temp0
        bcc     L4DB9
        adda    >DLTMAP_MapHysteresisAtMapCellBoundaries ; DLTMAP: Map Hysteresis At Map Cell Boundaries
L4DB9:
        cmpa    <MapValue
        bcc     L4DC9
        inx

;---------------------------------------------------------------------------------------------------
; ONTHROTTLE_OR_RPMTOOHIGHFORIDLE  ($4DBE)
;---------------------------------------------------------------------------------------------------
ONTHROTTLE_OR_RPMTOOHIGHFORIDLE:
        ldaa    <Temp0
        adda    #$02
        staa    <Temp0
        cpx     #MP5_AutoCalMapCellBoundary5         ; MP5: AutoCalMapCellBoundary1
        bls     L4DB0
L4DC9:
        ldaa    >R1_RPMCellBoundaryInRPMover32       ; R1: RPM Cell Boundary
        lsrb
        bcs     L4DD2
        adda    >DLTRPM_DeltaRPMAtRPMBoundariesInRPMOver32 ; DLTRPM: Delta RPM at RPM Boundaries
L4DD2:
        ldab    <Temp0
        cmpa    <EngineRpm_HB
        bcs     L4DD9
        decb
L4DD9:
        decb
L4DDA:
        bclr    <BitFlags37,#$80
        cmpb    <PointerIntoAdaptiveMemory
        beq     L4E00
        bset    <BitFlags37,#$80
        clra
        staa    <AdaptiveCellUpdateTimer_IncrementedEveryCamRisingEdge
        staa    <CylTrim_Adaptive_Var1
        ldaa    #$20
        cmpb    >CL2PTR_Cyl2AdaptiveMemoryPointer    ; CL2PTR (Cyl2AdaptiveMemoryPointer)
        beq     L4DFC
        lsra
        cmpb    >CL1PTR_Cyl1AdaptiveMemoryPointer    ; CL1PTR (Cyl1AdaptiveMemoryPointer)
        beq     L4DFC
        lsra
        cmpb    >CL3PTR_Cyl3AdaptiveMemoryPointer    ; CL3PTR (Cyl3AdaptiveMemoryPointer)
        bne     L4E00
L4DFC:
        eora    <CylTrim_Flags_1
        staa    <CylTrim_Flags_1
L4E00:
        stab    <PointerIntoAdaptiveMemory
        rts


;---------------------------------------------------------------------------------------------------
; ClearO2SensorFeedbackCounterSigned_MM  ($4E03)
;
; Resets the closed-loop feedback counter in a defined condition. [reviewed]
;
; Clears Counter_O2SensorFeedbackCount_Signed when it is below LC46E, Temp1_X is above LC46F, MAP
; is within LC470 of baro, coolant is above LC471, the car is slower than LC472 (VehicleSpeed_HB),
; the engine has run longer than LC473 and BitFlags37 bit 7 is set.
;
; Called from: MainSubLoop
;---------------------------------------------------------------------------------------------------
ClearO2SensorFeedbackCounterSigned_MM:
        ldaa    <Counter_O2SensorFeedbackCount_Signed
        cmpa    >LC46E                               ; BOOSTP: Zero percent limit on lean O2CNTR if MAP gt BOOSTP and no PTE
        bcc     L4E3B
        ldaa    >Temp1_X
        cmpa    >LC46F                               ; BOOSTP: Zero percent limit on lean O2CNTR if MAP gt BOOSTP and no PTE
        ble     L4E3B
        ldaa    <MapValue
        ldab    <BaroPressure
        subb    >LC470                               ; BOOSTP: Zero percent limit on lean O2CNTR if MAP gt BOOSTP and no PTE
        bcc     L4E1C
        clrb
L4E1C:
        cba
        bls     L4E3B
        ldaa    <CoolantTemp
        cmpa    >LC471                               ; BOOSTP: Zero percent limit on lean O2CNTR if MAP gt BOOSTP and no PTE
        bls     L4E3B
        ldaa    <VehicleSpeed_HB
        cmpa    >LC472                               ; BOOSTP: Zero percent limit on lean O2CNTR if MAP gt BOOSTP and no PTE
        bcc     L4E3B
        ldaa    <EngineRunningTimeMaxFF
        cmpa    >LC473                               ; BOOSTP: Zero percent limit on lean O2CNTR if MAP gt BOOSTP and no PTE
        bls     L4E3B
        brclr   <BitFlags37,#$80,L4E3B
        clr     >Counter_O2SensorFeedbackCount_Signed
L4E3B:
        rts


;---------------------------------------------------------------------------------------------------
; HandleAmTimer_MM  ($4E3C)
;
; Key-on set-up of the closed-loop timers. [reviewed]
;
; While the engine is not running it loads the AM timer from AMTPSW(coolant) and the closed-loop
; timer CLTIME from coolant temperature, clears BitFlags65 bit 5 and sets FuelSystemStatus to 1
; (open loop).
;
; Called from: MainSubLoop
;---------------------------------------------------------------------------------------------------
HandleAmTimer_MM:
        brclr   <BitFlags71,#$80,AMTimer_EngineRunning ; engine not running (stopped or cranking)
        ldaa    <CoolantTemp
        ldx     #AMTPSW_TempPointToEnableSelectedAMTimer ; AMTPSW: AM temp inhibit time from coolant temp
        jsr     >Lookup4ByteTable                    ; 2D table lookup with linear interpolation ("point-slope" format).
        staa    <Timer_O2CNTR_CountdownFromAbove196FtoEnableClosedLoop
        ldaa    <CoolantTemp
        ldx     #CLTIME_ClosedLoopTimeFromEngTempAtStartup_FromTemp ; CLTIME: Leave at one - 2.8 sec
        jsr     >Lookup4ByteTable                    ; 2D table lookup with linear interpolation ("point-slope" format).
        staa    <Timer_CLTIME_ClosedLoopTimer
        bclr    <BitFlags65,#$20                     ; closed-loop timer CLTIME expired
        ldaa    #$01
        staa    >FuelSystemStatus

;---------------------------------------------------------------------------------------------------
; AMTimer_EngineRunning  ($4E5C)
;---------------------------------------------------------------------------------------------------
AMTimer_EngineRunning:
        ldaa    <CoolantTemp
        ldab    <Counter_MainLoop
        bne     L4E7B
        cmpa    >AMTEMP_StartTempToSelectHotOrColdAMTimer ; AMTEMP: Starting Temp to select hot or cold AM timer
        bcs     L4E6F
        ldab    <Timer_O2CNTR_CountdownFromAbove196FtoEnableClosedLoop
        beq     L4E7B
        decb
        stab    <Timer_O2CNTR_CountdownFromAbove196FtoEnableClosedLoop
        rts

L4E6F:
        bne     L4E7B
        ldaa    <CoolantTemp
        ldx     #AMTPSW_TempPointToEnableSelectedAMTimer ; AMTPSW: AM temp inhibit time from coolant temp
        jsr     >Lookup4ByteTable                    ; 2D table lookup with linear interpolation ("point-slope" format).
        staa    <Timer_O2CNTR_CountdownFromAbove196FtoEnableClosedLoop
L4E7B:
        rts
